#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    unordered_map<string, long long> frequency;
    frequency.reserve(N * 2);

    for (int i = 0; i < N; ++i) {
        string password;
        cin >> password;
        ++frequency[password];
    }

    long long answer = 0;

    for (const auto& [password, count] : frequency) {
        vector<string> substrings;

        for (int start = 0; start < static_cast<int>(password.size()); ++start) {
            for (int length = 1; start + length <= static_cast<int>(password.size()); ++length) {
                string sub = password.substr(start, length);
                if (find(substrings.begin(), substrings.end(), sub) == substrings.end()) {
                    substrings.push_back(std::move(sub));
                }
            }
        }

        for (const string& sub : substrings) {
            auto it = frequency.find(sub);
            if (it != frequency.end()) {
                answer += count * it->second;
            }
        }

        answer -= count;
    }

    cout << answer << '\n';
    return 0;
}
